<?php
namespace App\Services;
final class PublicWebhookUrl{public function validate(string$url):string{$parts=parse_url($url);abort_unless(is_array($parts)&&($parts['scheme']??'')==='https'&&!empty($parts['host']),422,'El webhook debe usar una URL HTTPS válida');abort_if(isset($parts['user'])||isset($parts['pass']),422,'La URL del webhook no puede incluir credenciales');$host=strtolower(rtrim($parts['host'],'.'));abort_if($host==='localhost'||str_ends_with($host,'.localhost'),422,'El destino del webhook no es público');$ips=filter_var($host,FILTER_VALIDATE_IP)?[$host]:(gethostbynamel($host)?:[]);abort_if($ips===[],422,'No se pudo resolver el destino del webhook');foreach($ips as$ip)abort_unless(filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE),422,'El destino del webhook no es público');return$url;}}
